<?php
use App\Services\{DamageCalculator,BattleEngine};
use App\Models\Monster;
$calc=new DamageCalculator();$engine=new BattleEngine($cards);$deck=array_merge(array_keys($cards),array_keys($cards));
test('Dano direto é calculado a partir do ATK no servidor',function()use($calc){same(1000,$calc->calculate(['attack'=>1000,'ability'=>''],null,1)['damage']);});
test('Defesa e mínimo de dano',function()use($calc){same(600,$calc->calculate(['attack'=>1000],['defense'=>400,'hp'=>1000],1)['damage']);same(100,$calc->calculate(['attack'=>100],['defense'=>900,'hp'=>1000],1)['damage']);});
test('Escudo e excesso de dano',function()use($calc){$r=$calc->calculate(['attack'=>1800],['defense'=>300,'hp'=>500,'ability'=>'shield'],1);same(1300,$r['damage']);same(800,$r['overflow']);});
test('Brasas, perfuração e geada têm regras independentes',function()use($calc){same(1120,$calc->calculate(['attack'=>1000,'ability'=>'burn'],null,1)['damage']);same(160,$calc->calculate(['attack'=>1000,'ability'=>'pierce'],['defense'=>400,'hp'=>1000],1)['piercing']);same(800,$calc->calculate(['attack'=>1000,'weakened_until'=>3],null,3)['damage']);same(1000,$calc->calculate(['attack'=>1000,'weakened_until'=>3],null,4)['damage']);});
test('Abertura: 4000 PV, mão de cinco, deck persistível',function()use($engine,$deck){$s=$engine->start($deck,$deck);same(4000,$s['player']['hp']);same(5,count($s['player']['hand']));same(7,count($s['player']['deck']));same('player',$s['active_side']);});
test('Uma invocação por turno e custo de energia',function()use($engine,$deck){$s=$engine->start($deck,$deck);$s['player']['hand']=[1,2];$engine->summon($s,'player',1);same(0,$s['player']['energy']);same(1,count($s['player']['field']));rejects(fn()=>$engine->summon($s,'player',2));});
test('Invocação aceita IDs de cartas serializados como texto após restaurar a sala',function()use($engine,$deck){$s=$engine->start($deck,$deck);$s['player']['hand']=array_map('strval',$s['player']['hand']);$id=(int)$s['player']['hand'][0];$before=count($s['player']['hand']);$engine->summon($s,'player',$id);same(1,count($s['player']['field']));same($before-1,count($s['player']['hand']));});
test('Não invoca carta ausente, sem energia ou com campo cheio',function()use($engine,$deck,$cards){$s=$engine->start($deck,$deck);$s['player']['hand']=[1];rejects(fn()=>$engine->summon($s,'player',2));$s['player']['energy']=0;rejects(fn()=>$engine->summon($s,'player',1));$s['player']['energy']=10;$s['player']['field']=array_fill(0,3,Monster::summon($cards[1],1));rejects(fn()=>$engine->summon($s,'player',1));});
test('Ataque único, alvo obrigatório e proteção do campo',function()use($engine,$deck,$cards){$s=$engine->start($deck,$deck);$s['player']['field']=[Monster::summon($cards[1],1)];$s['ai']['field']=[Monster::summon($cards[2],2)];rejects(fn()=>$engine->attack($s,'player',1,null));rejects(fn()=>$engine->attack($s,'player',1,999));$engine->attack($s,'player',1,2);rejects(fn()=>$engine->attack($s,'player',1,2));rejects(fn()=>$engine->attack($s,'ai',2,1));});
test('Vitória, derrota e ações após encerramento',function()use($engine,$deck,$cards){$s=$engine->start($deck,$deck);$s['player']['field']=[Monster::summon($cards[1],1)];$s['ai']['hp']=100;$engine->attack($s,'player',1,null);same('finished',$s['status']);same('player',$s['winner']);rejects(fn()=>$engine->summon($s,'player',2));$s=$engine->start($deck,$deck);$s['player']['hp']=100;$s['ai']['field']=[Monster::summon($cards[1],8)];$engine->endTurn($s);same('ai',$s['winner']);});
test('Fim de turno executa IA, compra e restaura energia',function()use($engine,$deck){$s=$engine->start($deck,$deck);$s['player']['energy']=0;$engine->endTurn($s);same(3,$s['turn']);same('player',$s['active_side']);same(4,$s['player']['energy']);same(6,count($s['player']['hand']));check(count($s['ai']['field'])===1);});
test('Floresta regenera e sombras recuperam vida',function()use($engine,$deck,$cards){$s=$engine->start($deck,$deck);$s['player']['hp']=3000;$s['player']['field']=[Monster::summon($cards[6],1)];$engine->attack($s,'player',1,null);same(3362,$s['player']['hp']);$s=$engine->start($deck,$deck);$m=Monster::summon($cards[4],1);$m['hp']=500;$s['player']['field']=[$m];$s['ai']['hand']=[];$s['ai']['deck']=[];$engine->endTurn($s);same(700,$s['player']['field'][0]['hp']);});
test('Fadiga crescente encerra uma partida sem cartas',function()use($engine,$deck){$s=$engine->start($deck,$deck);$s['player']['deck']=[];$s['player']['hand']=[];$s['ai']['deck']=[];$s['ai']['hand']=[];for($i=0;$i<20&&$s['status']==='active';$i++)$engine->endTurn($s);same('finished',$s['status']);});

test('Roubo de vida e estatísticas consideram somente dano efetivo',function()use($engine,$deck,$cards){$s=$engine->start($deck,$deck);$s['player']['hp']=3000;$s['ai']['hp']=100;$s['player']['field']=[Monster::summon($cards[6],1)];$engine->attack($s,'player',1,null);same(3025,$s['player']['hp']);same(100,$s['damage_dealt']);});
